/// Returns the minimal number of fixed‐size steps of 5 needed to reach or exceed `x`.
///
/// Since `x >= 1`, this computes `ceil(x / 5)` without overflow in the `i8` domain.
fn min_steps(x: i8) -> i8 {
    // For x >= 1, (x - 1) is in [0, 126], so it won't overflow.
    // Integer division on positive values in Rust truncates toward zero, so
    // (x - 1) / 5 is floor((x - 1) / 5). Adding 1 yields ceil(x / 5).
    (x - 1) / 5 + 1
}

